  input VCC,
  input GND,
  input D1,
  input D2,
  input D3,
  input \~E ,
  input D4,
  input D5,
  input D6,
  input D7,
  input CLK,
  output Q0,
  output Q1,
  output Q2,
  output Q3,
  output Q4,
  output Q5,
  output Q6,
  output Q7
);
  wire s0;
  wire s1;
  wire Q0_temp;
  wire s2;
  wire Q1_temp;
  wire s3;
  wire Q2_temp;
  wire s4;
  wire Q3_temp;
  wire s5;
  wire Q4_temp;
  wire s6;
  wire Q5_temp;
  wire s7;
  wire Q6_temp;
  wire s8;
  wire Q7_temp;
  assign s1 = ~ \~E ;
  assign s0 = ((Q0_temp & \~E ) | (D0 & s1));
  assign s2 = ((Q1_temp & \~E ) | (D1 & s1));
  assign s3 = ((Q2_temp & \~E ) | (D2 & s1));
  assign s4 = ((Q3_temp & \~E ) | (D3 & s1));
  assign s5 = ((Q4_temp & \~E ) | (D4 & s1));
  assign s6 = ((Q5_temp & \~E ) | (D5 & s1));
  assign s7 = ((Q6_temp & \~E ) | (D6 & s1));
  assign s8 = ((Q7_temp & \~E ) | (D7 & s1));
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i0 (
    .D( s0 ),
    .C( CLK ),
    .Q( Q0_temp )
  );
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i1 (
    .D( s2 ),
    .C( CLK ),
    .Q( Q1_temp )
  );
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i2 (
    .D( s3 ),
    .C( CLK ),
    .Q( Q2_temp )
  );
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i3 (
    .D( s4 ),
    .C( CLK ),
    .Q( Q3_temp )
  );
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i4 (
    .D( s5 ),
    .C( CLK ),
    .Q( Q4_temp )
  );
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i5 (
