    .Q( Q6_temp )
  );
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i7 (
    .D( s8 ),
    .C( CLK ),
    .Q( Q7_temp )
  );
  assign Q0 = Q0_temp;
  assign Q1 = Q1_temp;
